param([string]$ProjectRoot="C:\Projekte\LSZJ_flightlist")
$ErrorActionPreference='Stop';$p=Join-Path $ProjectRoot 'public\dashboard.php';if(-not(Test-Path $p)){throw "Datei fehlt: $p"};$s=[IO.File]::ReadAllText($p);$old="html+='<p>Keine exportbereiten Flüge oder Freigaben fehlen.</p>';";$new="let reasons=[];if(exp.pending)reasons.push(exp.pending+' offene Einträge');if(exp.correction_required)reasons.push(exp.correction_required+' Korrekturen');if(exp.validation_summary)Object.entries(exp.validation_summary).forEach(([k,v])=>reasons.push(v+' × '+k));html+='<p>Export nicht möglich'+(reasons.length?': '+reasons.map(esc).join(', '):'. Keine freigegebenen, noch nicht exportierten Einträge.')+'</p>';";if($s.Contains($old)){Copy-Item $p "$p.bak-$(Get-Date -Format yyyyMMdd_HHmmss)";$s=$s.Replace($old,$new);[IO.File]::WriteAllText($p,$s,(New-Object Text.UTF8Encoding($false)));Write-Host 'Dashboard-Exportmeldung präzisiert.'}else{Write-Warning 'Dashboard-Marker nicht gefunden. Kernprüfung ist trotzdem installiert.'}
